mapper.sql:
WHERE knowledge_base_id=#{kb}
 AND object_type=#{objectType}
 AND change_type=#{changeType}

  AND (object_code LIKE CONCAT('%',#{keyword},'%')
    OR title LIKE CONCAT('%',#{keyword},'%')
    OR COALESCE(summary,'') LIKE CONCAT('%',#{keyword},'%'))

mapper.insert:
INSERT INTO t_knowledge_version(knowledge_base_id,object_type,object_code,version_no,title,summary,content,status,confidence,change_type,changed_by,supersedes_version_no)
SELECT #{kb},#{objectType},#{objectCode},COALESCE(v.max_version,0)+1,o.title,o.summary,o.content,o.status,o.confidence,#{changeType},#{changedBy},NULLIF(v.max_version,0)
FROM (
 SELECT k.title,k.summary,k.content,k.status,k.confidence FROM t_knowledge_card k
 WHERE #{objectType}='CARD' AND k.knowledge_base_id=#{kb} AND k.knowledge_code=#{objectCode}
 UNION ALL
 SELECT c.subject,c.predicate,c.object_value,c.status,c.confidence FROM t_claim c
 WHERE #{objectType}='CLAIM' AND c.knowledge_base_id=#{kb} AND c.claim_code=#{objectCode}
) o CROSS JOIN (SELECT COALESCE(MAX(version_no),0) max_version FROM t_knowledge_version WHERE object_type=#{objectType} AND object_code=#{objectCode}) v
